import{_ as t,o as r,c as e,a5 as n}from"./chunks/framework.Cooo9kuv.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"YSB0068-压缩备份指定文件夹里的文件到指定的文件夹","日期":"2026-04-11T00:00:00.000Z","修改日期":"2026-04-11T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["Bat批处理"],"标签":["批量压缩","批量压缩文件","批量压缩文件到指定文件夹","文件压缩工具"]},"headers":[{"level":2,"title":"压缩备份指定文件夹里的文件到指定的文件夹","slug":"压缩备份指定文件夹里的文件到指定的文件夹","link":"#压缩备份指定文件夹里的文件到指定的文件夹","children":[{"level":3,"title":"▶程序截图，可能随更新有些许变化","slug":"▶程序截图-可能随更新有些许变化","link":"#▶程序截图-可能随更新有些许变化","children":[]},{"level":3,"title":"▶【以下支持】：","slug":"▶【以下支持】","link":"#▶【以下支持】","children":[]},{"level":3,"title":"📑 使用场景例子展示","slug":"📑-使用场景例子展示","link":"#📑-使用场景例子展示","children":[]},{"level":3,"title":"**▶ **winrar程序安装说明，这步必须操作：","slug":"▶-winrar程序安装说明-这步必须操作","link":"#▶-winrar程序安装说明-这步必须操作","children":[]},{"level":3,"title":"📑 bat程序下一步执行方法","slug":"📑-bat程序下一步执行方法","link":"#📑-bat程序下一步执行方法","children":[]},{"level":3,"title":"📑 程序截图","slug":"📑-程序截图","link":"#📑-程序截图","children":[]},{"level":3,"title":"📑 程序使用环境及相关说明","slug":"📑-程序使用环境及相关说明","link":"#📑-程序使用环境及相关说明","children":[]}]}],"relativePath":"md/Bat批处理/YSB0068-压缩备份指定文件夹里的文件到指定的文件夹.md","filePath":"md/Bat批处理/YSB0068-压缩备份指定文件夹里的文件到指定的文件夹.md"}'),l={name:"md/Bat批处理/YSB0068-压缩备份指定文件夹里的文件到指定的文件夹.md"};function o(i,a,s,p,h,c){return r(),e("div",null,[...a[0]||(a[0]=[n('<h2 id="压缩备份指定文件夹里的文件到指定的文件夹" tabindex="-1">压缩备份指定文件夹里的文件到指定的文件夹 <a class="header-anchor" href="#压缩备份指定文件夹里的文件到指定的文件夹" aria-label="Permalink to &quot;压缩备份指定文件夹里的文件到指定的文件夹&quot;">​</a></h2><p>批量将指定文件夹下所有文件分别打包压缩到指定目标文件夹下，非常简单，程序放在哪里运行，压缩包的压缩包就会保存在哪里</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250221144949174012058930961.png" alt=""></p><h3 id="▶程序截图-可能随更新有些许变化" tabindex="-1"><strong>▶程序截图，可能随更新有些许变化</strong> <a class="header-anchor" href="#▶程序截图-可能随更新有些许变化" aria-label="Permalink to &quot;**▶程序截图，可能随更新有些许变化**&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/image-3.png" alt=""></p><h3 id="▶【以下支持】" tabindex="-1"><strong>▶【以下支持】：</strong> <a class="header-anchor" href="#▶【以下支持】" aria-label="Permalink to &quot;**▶【以下支持】：**&quot;">​</a></h3><p>【1】、支持的文件格式：所有文件类型</p><p>【2】、是否支持子文件夹穿透：不支持</p><h3 id="📑-使用场景例子展示" tabindex="-1">📑 使用场景例子展示 <a class="header-anchor" href="#📑-使用场景例子展示" aria-label="Permalink to &quot;📑 使用场景例子展示&quot;">​</a></h3><p>A文件夹下有很多不同类型的文件，同时有B、C、D....等文件夹，B、C、D....等这些文件夹下边还有子文件夹，子文件夹下也有文件。</p><p>【操作方法】：如果要将A文件夹下每个文件分别压缩，则打开程序后，将A文件夹拖入到程序中，然后回车键确认即可，程序放在哪个文件夹下，压缩后的文件就会保存在哪个文件夹下，不支持B、C、D....等文件夹下压缩包的解压，如果需要处理B、C、D....等文件夹下的文件需要单独进行处理。</p><h3 id="▶-winrar程序安装说明-这步必须操作" tabindex="-1">**▶ **winrar程序安装说明，这步必须操作： <a class="header-anchor" href="#▶-winrar程序安装说明-这步必须操作" aria-label="Permalink to &quot;**▶ **winrar程序安装说明，这步必须操作：&quot;">​</a></h3><p>注意：安装路径必须为此处：D:\\rar\\，**提示：**请提前在D盘创建文件夹：rar</p><p>如果没有D盘，则安装在C盘，然后修改代码部分即可，如下所示：</p><p>将代码中的这部分代码 set &quot;winrarpath=D:\\rar\\rar.exe&quot; 修改为 set &quot;winrarpath=C:\\rar\\rar.exe&quot; 即可</p><h3 id="📑-bat程序下一步执行方法" tabindex="-1">📑 bat程序下一步执行方法 <a class="header-anchor" href="#📑-bat程序下一步执行方法" aria-label="Permalink to &quot;📑 bat程序下一步执行方法&quot;">​</a></h3><p>**▶ **使用时，<strong>键盘回车键（就是键盘上的 ENTER 键）</strong>“回车确认”是执行下一步的方法 ，</p><p>比如将路径复制到程序中后，回车键确认执行下一步，每一步输入后，回车键确认即可向下执行。</p><p><strong>▶ 注意：请先测试备份原文件再批量使用，以免造成不可逆损失！！！</strong></p><h3 id="📑-程序截图" tabindex="-1">📑 程序截图 <a class="header-anchor" href="#📑-程序截图" aria-label="Permalink to &quot;📑 程序截图&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250221144845174012052558785.png" alt=""></p><h3 id="📑-程序使用环境及相关说明" tabindex="-1">📑 程序使用环境及相关说明 <a class="header-anchor" href="#📑-程序使用环境及相关说明" aria-label="Permalink to &quot;📑 程序使用环境及相关说明&quot;">​</a></h3><blockquote><p><strong>1、适用的系统环境说明</strong>：建议win7及以上64位win操作系统，mac系统需要定制。</p><p><strong>注意事项：bat程序原理上是支持</strong>win32位系统的，但不能完全确定。</p><p><strong>2、使用期限</strong>： 无需注册、无需密码、不绑定电脑、无使用时间限制</p><p><strong>3、如何安装</strong>：程序不需要安装，按照说明使用即可</p><p><strong>特别注意 - 特别声明</strong>：请先测试，注意备份原文件，避免不可逆损失，之后再批量使用</p></blockquote><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/1360.html" target="_blank" rel="noreferrer">https://www.softbangong.com/1360.html</a></p>',25)])])}const _=t(l,[["render",o]]);export{g as __pageData,_ as default};
